export { default as Threads } from './Threads.vue';
export { isThreadsPreset, threadsPreset } from './threads-presets';
export type {
  ThreadsColor,
  ThreadsLook,
  ThreadsPreset,
  ThreadsProps,
} from './types';

import {
  THREADS_LINE_FRAGMENT,
  THREADS_LINE_VERTEX,
  THREADS_SCREEN_FRAGMENT,
  THREADS_SCREEN_VERTEX,
} from './threads-shaders';
import type {
  ThreadsColor,
  ThreadsEngine,
  ThreadsProps,
  ThreadsSettings,
} from './types';

const MAX_RENDER_DIM = 1920;

const LINE_UNIFORMS = [
  'uTime',
  'uResolution',
  'uFrame',
  'uAmplitude',
  'uDistance',
  'uMouse',
  'uCount',
  'uThickness',
  'uSoftness',
  'uWaves',
  'uSplit',
  'uFray',
  'uSeed',
  'uTurn',
  'uPart',
  'uTaper',
  'uColor',
  'uAccent',
];
const SCREEN_UNIFORMS = [
  'uLines',
  'uResolution',
  'uFade',
  'uOpacity',
  'uCurve',
];

type Uniforms = Record<string, WebGLUniformLocation | null>;
type Rgb = [number, number, number];
type Vec2 = [number, number];

interface EngineState {
  time: number;
  width: number;
  height: number;
  segments: number;
  colorKey: string;
  color: Rgb;
  accent: Rgb;
  mouse: [number, number];
  targetMouse: [number, number];
  pointer: [number, number];
  targetPointer: [number, number];
  presence: number;
  inside: boolean;
}

const clamp = (value: number, min: number, max: number) =>
  Math.min(max, Math.max(min, value));

const colorKeyOf = (value: ThreadsColor | undefined) =>
  Array.isArray(value) ? value.join(',') : String(value ?? '');

/** Resolves props into the clamped settings the renderer reads. */
export function toThreadsSettings(props: ThreadsProps): ThreadsSettings {
  const color = props.color ?? [1, 1, 1];
  return {
    color,
    accentColor: props.accentColor,
    colorKey: `${colorKeyOf(color)}|${colorKeyOf(props.accentColor)}`,
    amplitude: props.amplitude ?? 1.7,
    distance: props.distance ?? 0.4,
    enableMouseInteraction: props.enableMouseInteraction ?? false,
    lineCount: clamp(Math.round(props.lineCount ?? 90), 1, 400),
    thickness: Math.max(0, props.thickness ?? 0.6),
    softness: Math.max(0, props.softness ?? 1.3),
    speed: props.speed ?? 0.6,
    waves: Math.max(0, props.waves ?? 1.05),
    split: clamp(props.split ?? 0.04, 0, 1),
    fray: clamp(props.fray ?? 0.5, 0, 1),
    angle: props.angle ?? 25,
    seed: props.seed ?? 0,
    parting: clamp(props.parting ?? 0, 0, 1),
    taper: clamp(props.taper ?? 0.85, 0, 1),
    brightness: clamp(props.brightness ?? 1.4, 0.25, 2),
    fade: clamp(props.fade ?? 0, 0, 1),
    opacity: clamp(props.opacity ?? 1, 0, 1),
    paused: props.paused ?? false,
  };
}

function compile(gl: WebGL2RenderingContext, type: number, source: string) {
  const shader = gl.createShader(type);
  if (!shader) return null;
  gl.shaderSource(shader, source);
  gl.compileShader(shader);
  if (gl.getShaderParameter(shader, gl.COMPILE_STATUS)) return shader;
  gl.deleteShader(shader);
  return null;
}

function link(
  gl: WebGL2RenderingContext,
  vertexSource: string,
  fragmentSource: string,
) {
  const vertex = compile(gl, gl.VERTEX_SHADER, vertexSource);
  const fragment = compile(gl, gl.FRAGMENT_SHADER, fragmentSource);
  const program = gl.createProgram();
  if (!vertex || !fragment || !program) return null;
  gl.attachShader(program, vertex);
  gl.attachShader(program, fragment);
  gl.linkProgram(program);
  gl.deleteShader(vertex);
  gl.deleteShader(fragment);
  if (gl.getProgramParameter(program, gl.LINK_STATUS)) return program;
  gl.deleteProgram(program);
  return null;
}

function locate(
  gl: WebGL2RenderingContext,
  program: WebGLProgram,
  names: string[],
): Uniforms {
  const result: Uniforms = {};
  for (const name of names) result[name] = gl.getUniformLocation(program, name);
  return result;
}

/**
 * Draws every thread as one instanced triangle strip into an offscreen
 * target, then composites it with brightness, edge fade and opacity.
 */
export function createThreadsEngine(
  canvas: HTMLCanvasElement,
  getSettings: () => ThreadsSettings,
  isReduced: () => boolean,
): ThreadsEngine | null {
  const gl = canvas.getContext('webgl2', {
    alpha: true,
    premultipliedAlpha: true,
    antialias: false,
    depth: false,
    stencil: false,
  });
  if (!gl) return null;

  const lineProgram = link(gl, THREADS_LINE_VERTEX, THREADS_LINE_FRAGMENT);
  const screenProgram = link(
    gl,
    THREADS_SCREEN_VERTEX,
    THREADS_SCREEN_FRAGMENT,
  );
  if (!lineProgram || !screenProgram) return null;

  const lineUniforms = locate(gl, lineProgram, LINE_UNIFORMS);
  const screenUniforms = locate(gl, screenProgram, SCREEN_UNIFORMS);

  const lineVao = gl.createVertexArray();
  const lineBuffer = gl.createBuffer();
  gl.bindVertexArray(lineVao);
  gl.bindBuffer(gl.ARRAY_BUFFER, lineBuffer);
  const pointLocation = gl.getAttribLocation(lineProgram, 'aPoint');
  gl.enableVertexAttribArray(pointLocation);
  gl.vertexAttribPointer(pointLocation, 2, gl.FLOAT, false, 0, 0);

  const screenVao = gl.createVertexArray();
  const screenBuffer = gl.createBuffer();
  gl.bindVertexArray(screenVao);
  gl.bindBuffer(gl.ARRAY_BUFFER, screenBuffer);
  gl.bufferData(
    gl.ARRAY_BUFFER,
    new Float32Array([-1, -1, 3, -1, -1, 3]),
    gl.STATIC_DRAW,
  );
  const positionLocation = gl.getAttribLocation(screenProgram, 'aPosition');
  gl.enableVertexAttribArray(positionLocation);
  gl.vertexAttribPointer(positionLocation, 2, gl.FLOAT, false, 0, 0);
  gl.bindVertexArray(null);

  const target = gl.createTexture();
  const framebuffer = gl.createFramebuffer();
  gl.bindTexture(gl.TEXTURE_2D, target);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.NEAREST);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.NEAREST);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);

  const probe = document.createElement('canvas');
  probe.width = 1;
  probe.height = 1;
  const probeContext = probe.getContext('2d', { willReadFrequently: true });

  const state: EngineState = {
    time: 0,
    width: 1,
    height: 1,
    segments: 0,
    colorKey: '\u0000',
    color: [1, 1, 1],
    accent: [1, 1, 1],
    mouse: [0.5, 0.5],
    targetMouse: [0.5, 0.5],
    pointer: [0, 0],
    targetPointer: [0, 0],
    presence: 0,
    inside: false,
  };
  let last = 0;

  const toRgb = (value: ThreadsColor): Rgb => {
    if (Array.isArray(value)) {
      return [
        clamp(Number(value[0] ?? 1), 0, 1),
        clamp(Number(value[1] ?? 1), 0, 1),
        clamp(Number(value[2] ?? 1), 0, 1),
      ];
    }
    if (!probeContext) return [1, 1, 1];
    probeContext.clearRect(0, 0, 1, 1);
    probeContext.fillStyle = '#ffffff';
    probeContext.fillStyle = String(value);
    probeContext.fillRect(0, 0, 1, 1);
    const data = probeContext.getImageData(0, 0, 1, 1).data;
    return [
      (data[0] ?? 255) / 255,
      (data[1] ?? 255) / 255,
      (data[2] ?? 255) / 255,
    ];
  };

  const resolveColors = (s: ThreadsSettings) => {
    if (s.colorKey === state.colorKey) return;
    state.colorKey = s.colorKey;
    state.color = toRgb(s.color);
    state.accent =
      s.accentColor === undefined || s.accentColor === ''
        ? state.color
        : toRgb(s.accentColor);
  };

  const buildStrip = (segments: number) => {
    if (segments === state.segments) return;
    state.segments = segments;
    const points = new Float32Array((segments + 1) * 4);
    for (let i = 0; i <= segments; i++) {
      const u = i / segments;
      points.set([u, -1, u, 1], i * 4);
    }
    gl.bindBuffer(gl.ARRAY_BUFFER, lineBuffer);
    gl.bufferData(gl.ARRAY_BUFFER, points, gl.STATIC_DRAW);
  };

  const render = () => {
    const s = getSettings();
    resolveColors(s);
    const w = canvas.width;
    const h = canvas.height;
    const radians = (s.angle * Math.PI) / 180;
    const cos = Math.cos(radians);
    const sin = Math.sin(radians);
    const length = Math.abs(w * cos) + Math.abs(h * sin);
    const across = Math.abs(w * sin) + Math.abs(h * cos);
    const scale = w / state.width;
    const mouse: Vec2 = s.enableMouseInteraction ? state.mouse : [0.5, 0.5];
    const strength = s.parting * state.presence * 2;
    const px = state.pointer[0] * scale;
    const py = state.pointer[1] * scale;
    const localX = px * cos + py * sin;
    const localY = -px * sin + py * cos;

    gl.bindFramebuffer(gl.FRAMEBUFFER, framebuffer);
    gl.viewport(0, 0, w, h);
    gl.clearColor(0, 0, 0, 0);
    gl.clear(gl.COLOR_BUFFER_BIT);
    gl.enable(gl.BLEND);
    gl.blendFunc(gl.ONE, gl.ONE_MINUS_SRC_ALPHA);
    gl.useProgram(lineProgram);
    const u = lineUniforms;
    gl.uniform1f(u.uTime ?? null, state.time);
    gl.uniform2f(u.uResolution ?? null, w, h);
    gl.uniform2f(u.uFrame ?? null, length, across);
    gl.uniform1f(u.uAmplitude ?? null, s.amplitude);
    gl.uniform1f(u.uDistance ?? null, s.distance);
    gl.uniform2f(u.uMouse ?? null, mouse[0], mouse[1]);
    gl.uniform1f(u.uCount ?? null, s.lineCount);
    gl.uniform1f(u.uThickness ?? null, s.thickness);
    gl.uniform1f(u.uSoftness ?? null, s.softness);
    gl.uniform1f(u.uWaves ?? null, s.waves);
    gl.uniform1f(u.uSplit ?? null, s.split);
    gl.uniform1f(u.uFray ?? null, s.fray);
    gl.uniform1f(u.uSeed ?? null, s.seed * 13.37);
    gl.uniform2f(u.uTurn ?? null, cos, sin);
    gl.uniform4f(
      u.uPart ?? null,
      localX,
      localY,
      strength,
      Math.min(w, h) * 0.16,
    );
    gl.uniform1f(u.uTaper ?? null, s.taper);
    gl.uniform3f(
      u.uColor ?? null,
      state.color[0],
      state.color[1],
      state.color[2],
    );
    gl.uniform3f(
      u.uAccent ?? null,
      state.accent[0],
      state.accent[1],
      state.accent[2],
    );
    gl.bindVertexArray(lineVao);
    gl.drawArraysInstanced(
      gl.TRIANGLE_STRIP,
      0,
      (state.segments + 1) * 2,
      s.lineCount,
    );

    gl.bindFramebuffer(gl.FRAMEBUFFER, null);
    gl.viewport(0, 0, w, h);
    gl.disable(gl.BLEND);
    gl.clear(gl.COLOR_BUFFER_BIT);
    gl.useProgram(screenProgram);
    gl.activeTexture(gl.TEXTURE0);
    gl.bindTexture(gl.TEXTURE_2D, target);
    gl.uniform1i(screenUniforms.uLines ?? null, 0);
    gl.uniform2f(screenUniforms.uResolution ?? null, w, h);
    gl.uniform1f(screenUniforms.uFade ?? null, s.fade);
    gl.uniform1f(screenUniforms.uOpacity ?? null, s.opacity);
    gl.uniform1f(screenUniforms.uCurve ?? null, 2 / s.brightness);
    gl.bindVertexArray(screenVao);
    gl.drawArrays(gl.TRIANGLES, 0, 3);
    gl.bindVertexArray(null);
  };

  const resize = (cssWidth: number, cssHeight: number) => {
    const width = Math.max(1, cssWidth);
    const height = Math.max(1, cssHeight);
    const baseDpr = Math.min(window.devicePixelRatio || 1, 2);
    const longest = Math.max(width, height) * baseDpr;
    const dpr =
      longest > MAX_RENDER_DIM ? (baseDpr * MAX_RENDER_DIM) / longest : baseDpr;
    canvas.width = Math.max(1, Math.round(width * dpr));
    canvas.height = Math.max(1, Math.round(height * dpr));
    state.width = width;
    state.height = height;
    gl.bindTexture(gl.TEXTURE_2D, target);
    gl.texImage2D(
      gl.TEXTURE_2D,
      0,
      gl.RGBA,
      canvas.width,
      canvas.height,
      0,
      gl.RGBA,
      gl.UNSIGNED_BYTE,
      null,
    );
    gl.bindFramebuffer(gl.FRAMEBUFFER, framebuffer);
    gl.framebufferTexture2D(
      gl.FRAMEBUFFER,
      gl.COLOR_ATTACHMENT0,
      gl.TEXTURE_2D,
      target,
      0,
    );
    gl.bindFramebuffer(gl.FRAMEBUFFER, null);
    buildStrip(clamp(Math.round(width / 3), 96, 640));
    render();
  };

  const frame = (now: number) => {
    const s = getSettings();
    const dt = last ? Math.min(0.05, (now - last) / 1000) : 1 / 60;
    last = now;
    const moving = !s.paused && !isReduced();
    if (moving) state.time += dt * s.speed;
    const follow = 1 - Math.exp(-dt * 3);
    state.mouse[0] += (state.targetMouse[0] - state.mouse[0]) * follow;
    state.mouse[1] += (state.targetMouse[1] - state.mouse[1]) * follow;
    const glide = 1 - Math.exp(-dt * 10);
    state.pointer[0] += (state.targetPointer[0] - state.pointer[0]) * glide;
    state.pointer[1] += (state.targetPointer[1] - state.pointer[1]) * glide;
    const wanted = state.inside && s.parting > 0 ? 1 : 0;
    state.presence += (wanted - state.presence) * (1 - Math.exp(-dt * 4));
    render();
    const settling =
      Math.abs(state.targetMouse[0] - state.mouse[0]) > 0.0005 ||
      Math.abs(state.targetMouse[1] - state.mouse[1]) > 0.0005 ||
      Math.abs(state.targetPointer[0] - state.pointer[0]) > 0.05 ||
      Math.abs(state.targetPointer[1] - state.pointer[1]) > 0.05 ||
      Math.abs(wanted - state.presence) > 0.002;
    if (moving || settling) return true;
    last = 0;
    return false;
  };

  const pointerMove = (x: number, y: number, width: number, height: number) => {
    const nx = x / Math.max(1, width);
    const ny = y / Math.max(1, height);
    const inside = nx >= 0 && nx <= 1 && ny >= 0 && ny <= 1;
    if (inside) {
      state.targetMouse = [nx, 1 - ny];
      state.targetPointer = [x - width / 2, height / 2 - y];
      if (!state.inside && state.presence < 0.01) {
        state.pointer = [state.targetPointer[0], state.targetPointer[1]];
      }
    } else if (state.inside) {
      state.targetMouse = [0.5, 0.5];
    }
    state.inside = inside;
  };

  const pointerLeave = () => {
    state.inside = false;
    state.targetMouse = [0.5, 0.5];
  };

  const dispose = () => {
    gl.deleteFramebuffer(framebuffer);
    gl.deleteTexture(target);
    gl.deleteBuffer(lineBuffer);
    gl.deleteBuffer(screenBuffer);
    gl.deleteVertexArray(lineVao);
    gl.deleteVertexArray(screenVao);
    gl.deleteProgram(lineProgram);
    gl.deleteProgram(screenProgram);
    gl.getExtension('WEBGL_lose_context')?.loseContext();
  };

  return {
    frame,
    render,
    resize,
    pointerMove,
    pointerLeave,
    resetClock: () => {
      last = 0;
    },
    dispose,
  };
}

export const THREADS_LINE_VERTEX = `#version 300 es
precision highp float;
in vec2 aPoint;
uniform float uTime;
uniform vec2 uResolution;
uniform vec2 uFrame;
uniform float uAmplitude;
uniform float uDistance;
uniform vec2 uMouse;
uniform float uCount;
uniform float uThickness;
uniform float uSoftness;
uniform float uWaves;
uniform float uSplit;
uniform float uFray;
uniform float uSeed;
uniform vec2 uTurn;
uniform vec4 uPart;
uniform float uTaper;
out float vEdge;
out float vBand;
out float vDraw;
out float vAlpha;
out float vIndex;

float Perlin2D(vec2 P) {
  vec2 Pi = floor(P);
  vec4 Pf_Pfmin1 = P.xyxy - vec4(Pi, Pi + 1.0);
  vec4 Pt = vec4(Pi.xy, Pi.xy + 1.0);
  Pt = Pt - floor(Pt * (1.0 / 71.0)) * 71.0;
  Pt += vec2(26.0, 161.0).xyxy;
  Pt *= Pt;
  Pt = Pt.xzxz * Pt.yyww;
  vec4 hash_x = fract(Pt * (1.0 / 951.135664));
  vec4 hash_y = fract(Pt * (1.0 / 642.949883));
  vec4 grad_x = hash_x - 0.49999;
  vec4 grad_y = hash_y - 0.49999;
  vec4 grad_results = inversesqrt(grad_x * grad_x + grad_y * grad_y) * (grad_x * Pf_Pfmin1.xzxz + grad_y * Pf_Pfmin1.yyww);
  grad_results *= 1.4142135623730950;
  vec2 blend = Pf_Pfmin1.xy * Pf_Pfmin1.xy * Pf_Pfmin1.xy * (Pf_Pfmin1.xy * (Pf_Pfmin1.xy * 6.0 - 15.0) + 10.0);
  vec4 blend2 = vec4(blend, vec2(1.0 - blend));
  return dot(grad_results, blend2.zxzx * blend2.wwyy);
}

void main() {
  float perc = float(gl_InstanceID) / uCount;
  float x = aPoint.x;
  float pixel = 1.0 / max(uResolution.x, uResolution.y);
  float splitPoint = uSplit + perc * uFray;
  float amplitudeNormal = smoothstep(splitPoint, max(0.7, splitPoint + 0.2), x);
  float finalAmplitude = amplitudeNormal * 0.5 * uAmplitude * (1.0 + (uMouse.y - 0.5) * 0.2);
  float timeScaled = uTime / 10.0 + (uMouse.x - 0.5);
  float blur = smoothstep(splitPoint, splitPoint + 0.05, x) * perc;
  float xnoise = mix(
    Perlin2D(vec2(timeScaled * 2.5 + uSeed, (x * uWaves + perc) * 2.5)),
    Perlin2D(vec2(timeScaled * 3.5 + uSeed, (x * uWaves + timeScaled) * 3.5)) / 1.5,
    x * 0.3
  );
  float y = 0.5 + (perc - 0.5) * uDistance + xnoise / 2.0 * finalAmplitude;
  vec2 local = vec2((x - 0.5) * uFrame.x, (y - 0.5) * uFrame.y);
  if (uPart.z > 0.0) {
    vec2 delta = local - uPart.xy;
    float reach = uPart.w;
    float pull = exp(-dot(delta, delta) / (reach * reach));
    local.y += delta.y * pull * uPart.z;
  }
  float width = 7.0 * uThickness * pixel * (1.0 - perc);
  float band = (width / 2.0 + 10.0 * uSoftness * pixel * blur) * uFrame.y;
  float draw = max(band, 1.0);
  local.y += aPoint.y * draw;
  vec2 turned = vec2(local.x * uTurn.x - local.y * uTurn.y, local.x * uTurn.y + local.y * uTurn.x);
  gl_Position = vec4(turned / (uResolution * 0.5), 0.0, 1.0);
  vEdge = aPoint.y * draw;
  vBand = band;
  vDraw = draw;
  vAlpha = 1.0 - smoothstep(0.0, 1.0, pow(perc, 0.3)) * uTaper;
  vIndex = perc;
}`;

export const THREADS_LINE_FRAGMENT = `#version 300 es
precision highp float;
in float vEdge;
in float vBand;
in float vDraw;
in float vAlpha;
in float vIndex;
uniform vec3 uColor;
uniform vec3 uAccent;
out vec4 outColor;
void main() {
  float coverage = (1.0 - smoothstep(0.0, vDraw, abs(vEdge))) * (vBand / vDraw) * vAlpha;
  outColor = vec4(mix(uColor, uAccent, vIndex) * coverage, coverage);
}`;

export const THREADS_SCREEN_VERTEX = `#version 300 es
in vec2 aPosition;
out vec2 vUv;
void main() {
  vUv = aPosition * 0.5 + 0.5;
  gl_Position = vec4(aPosition, 0.0, 1.0);
}`;

export const THREADS_SCREEN_FRAGMENT = `#version 300 es
precision highp float;
in vec2 vUv;
uniform sampler2D uLines;
uniform vec2 uResolution;
uniform float uFade;
uniform float uOpacity;
uniform float uCurve;
out vec4 outColor;

float smootherstep(float edge, float x) {
  float t = clamp(x / edge, 0.0, 1.0);
  return t * t * t * (t * (t * 6.0 - 15.0) + 10.0);
}

void main() {
  vec4 lines = texture(uLines, vUv);
  float alpha = lines.a;
  vec3 color = alpha > 0.0001 ? lines.rgb / alpha : vec3(0.0);
  float mask = uOpacity;
  if (uFade > 0.0) {
    vec2 px = vUv * uResolution;
    float edge = uFade * min(uResolution.x, uResolution.y) * 0.5;
    mask *= smootherstep(edge, px.x) * smootherstep(edge, uResolution.x - px.x);
    mask *= smootherstep(edge, px.y) * smootherstep(edge, uResolution.y - px.y);
  }
  outColor = vec4(color * pow(alpha, uCurve), alpha) * mask;
}`;

/** Any CSS color, or an RGB array from 0 to 1. */
export type ThreadsColor = string | number[];

export type ThreadsPreset =
  | 'silk'
  | 'classic'
  | 'rope'
  | 'strands'
  | 'contour'
  | 'curtain';

export interface ThreadsProps {
  /** Color of the threads. Any CSS color, or an RGB array from 0 to 1. */
  color?: ThreadsColor;
  /** Color the outer threads blend toward. Leave it out for a single color. */
  accentColor?: ThreadsColor;
  /** Number of threads. */
  lineCount?: number;
  /** Width of the threads. */
  thickness?: number;
  /** How much the threads soften as they separate. 0 keeps every thread crisp. */
  softness?: number;
  /** Height of the waves. */
  amplitude?: number;
  /** Spacing between the threads. 0 starts them all from a single line. */
  distance?: number;
  /** How many waves run along each thread. */
  waves?: number;
  /** Animation speed. 0 holds the threads still. */
  speed?: number;
  /** Where the first thread leaves the bundle, from 0 at the start to 1 at the end. */
  split?: number;
  /** How gradually the other threads peel away after the first one. */
  fray?: number;
  /** Direction of the threads in degrees. */
  angle?: number;
  /** How much the outer threads fade away, from 0 for all equally bright to 1. */
  taper?: number;
  /** Brightness of the threads, from 0.25 to 2. */
  brightness?: number;
  /** How far the threads move aside around the cursor, from 0 to 1. */
  parting?: number;
  /** Lets the cursor steer the waves sideways and change their height. */
  enableMouseInteraction?: boolean;
  /** Fades the edges into the page, from 0 to 1. */
  fade?: number;
  /** Opacity of the whole effect. */
  opacity?: number;
  /** Changes the wave pattern. */
  seed?: number;
  /** Freezes the animation. */
  paused?: boolean;
  class?: string;
}

export interface ThreadsSettings {
  color: ThreadsColor;
  accentColor: ThreadsColor | undefined;
  colorKey: string;
  amplitude: number;
  distance: number;
  enableMouseInteraction: boolean;
  lineCount: number;
  thickness: number;
  softness: number;
  speed: number;
  waves: number;
  split: number;
  fray: number;
  angle: number;
  seed: number;
  parting: number;
  taper: number;
  brightness: number;
  fade: number;
  opacity: number;
  paused: boolean;
}

/** The props a demo preset sets. */
export interface ThreadsLook {
  lineCount: number;
  thickness: number;
  softness: number;
  amplitude: number;
  distance: number;
  waves: number;
  speed: number;
  split: number;
  fray: number;
  angle: number;
  taper: number;
  brightness: number;
  parting: number;
  enableMouseInteraction: boolean;
  fade: number;
  opacity: number;
  seed: number;
}

export interface ThreadsEngine {
  /** Advances one frame. Returns false once nothing is moving, so the loop can stop. */
  frame: (now: number) => boolean;
  /** Redraws with the current settings. */
  render: () => void;
  resize: (width: number, height: number) => void;
  pointerMove: (x: number, y: number, width: number, height: number) => void;
  pointerLeave: () => void;
  resetClock: () => void;
  dispose: () => void;
}
